import{_ as a,o as i,c as n,y as l}from"./chunks/framework.CNTkXYA8.js";const c=JSON.parse('{"title":"如何在CMake中独立构建外部项目","description":"","frontmatter":{"title":"如何在CMake中独立构建外部项目","date":"2025-08-30T11:08:26.000Z","tags":["cmake","C++","compile","build skills"],"how-to":true},"headers":[],"relativePath":"blog/cmake-external-project.md","filePath":"source/_posts/cmake-external-project.md"}'),t={name:"blog/cmake-external-project.md"};function p(e,s,h,k,E,d){return i(),n("div",null,[...s[0]||(s[0]=[l(`<p>有时候我们的CMake项目依赖两个项目，但这两个项目包含了相同的库，这些库构建相同名称的目标，但库版本以及库源代码有一些微小的改动。为了不破坏依赖项目的独立性以方便后续更新，我们需要一个完全独立的方式来构建这些库，就像单独运行一次CMake构建流程一样。</p><h1 id="fetchcontent" tabindex="-1">FetchContent <a class="header-anchor" href="#fetchcontent" aria-label="Permalink to &quot;FetchContent&quot;">​</a></h1><p>对那些高版本、良好配置的Cmake项目，我们可以直接通过FetchContent获取源代码并获得其构建目标，例如声明对spdlog的依赖，并使其可用（下载）：</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FetchContent_Declare(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    spdlog</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GIT_REPOSITORY https://github.com/gabime/spdlog.git</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GIT_TAG        v1.14.1</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">FetchContent_MakeAvailable(spdlog)</span></span></code></pre></div><p>之后，构建目标已经进入Cmake构建流程，直接使用即可：</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">target_link_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(my_app </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">PRIVATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> spdlog::spdlog)</span></span></code></pre></div><h1 id="externalproject-add" tabindex="-1">ExternalProject_Add <a class="header-anchor" href="#externalproject-add" aria-label="Permalink to &quot;ExternalProject_Add&quot;">​</a></h1><p>较为重型的方案，同时适合网络拉取和包含本地另外的Cmake项目。</p><p>对本地项目，假设我有一个生成可执行文件的项目Markerauto2：</p><ul><li>位置在该Cmake文件同目录</li><li>构建中间文件存放在[二进制目录]/MARKERAUTO2位置下（避免与主项目同名构建文件重名，例如使用同名库）</li><li>构建目标放在[二进制目录]/bin下</li></ul><p>可以如下操作：</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --- 生成模块程序Markerauto2 </span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExternalProject_Add(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Markerauto2 </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 为这个外部项目构建过程起一个唯一的名字</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 指定B的源代码目录</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    SOURCE_DIR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${CMAKE_CURRENT_SOURCE_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/Markerauto2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 指定B的构建目录，这会是 build/B_build/</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BINARY_DIR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${CMAKE_BINARY_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/MARKERAUTO2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CMAKE_ARGS </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        -DCMAKE_RUNTIME_OUTPUT_DIRECTORY:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">PATH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${CMAKE_BINARY_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/bin</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 关键：告诉 ExternalProject 我们不需要下载、更新或打补丁</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 因为源代码就在本地</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    DOWNLOAD_COMMAND </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UPDATE_COMMAND </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PATCH_COMMAND </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    INSTALL_COMMAND </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>类似的，对于远程项目，如下操作：</p><div class="language-cmake vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cmake</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExternalProject_Add(</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    spdlog_project </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 目标名称</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GIT_REPOSITORY https://github.com/gabime/spdlog.git</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    GIT_TAG        v1.14.1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 关闭我们不需要的步骤</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    UPDATE_COMMAND </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    PATCH_COMMAND </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    INSTALL_COMMAND </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 指定子项目的构建目录</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    BINARY_DIR </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${CMAKE_BINARY_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/spdlog-build</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 告诉子项目把它生成的库放到哪里</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    CMAKE_ARGS -DCMAKE_ARCHIVE_OUTPUT_DIRECTORY=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\${CMAKE_BINARY_DIR}</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/lib</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>需要注意的是，ExternalProject_Add不会暴露构建目标，是一次完全独立的构建，只会提供构建的目标文件本身，这也意味着你需要手动根据路径添加目标文件的链接、依赖。</p>`,15)])])}const o=a(t,[["render",p]]);export{c as __pageData,o as default};
